INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18801, 'Jeremiah 38:19', 'Jeremiah', 38, 19, '&nbsp;خو صدقياه بادشاه يرمياه ته ووئيل چې، ”زۀ د خپل مُلک د هغه خلقو نه يرېږم چا چې غدارى وکړه او بابليانو له ورغلل، کېدے شى چې د بابل فوجيان ما هغوئ ته حواله کړى او بيا به هغوئ ما سره بد سلوک وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18802, 'Jeremiah 38:20', 'Jeremiah', 38, 20, '&nbsp;يرمياه ورته وفرمائيل چې، ”هغوئ به تاسو چا ته نۀ حواله کوى کۀ چرې تۀ د مالِک خُدائ تابعدارى غوره کړې. هغه به ستا ژوند بچ کړى او تا ته به خير شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18803, 'Jeremiah 38:21', 'Jeremiah', 38, 21, '&nbsp;خو کۀ چرې تاسو نۀ غواړئ چې خپل ځان هغوئ ته حواله کړئ نو بيا مالِک خُدائ ما ته دا موضوع په رويا کښې ښکاره کړې ده چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18804, 'Jeremiah 38:22', 'Jeremiah', 38, 22, '&nbsp;څومره ښځې چې په دې شاهى محل کښې ژوندۍ پاتې وى نو هغوئ به فوجيان د بابليانو آفسرانو ته ستاسو نه بوځى. نو بيا به د تلو په وخت دا ښځې تاسو ته داسې پېغور درکوى او درته به وائى چې، ”ستاسو څومره ښۀ دوستان وُو، ټولو تاسو سره دوکه وکړه او بې‌لارې يې کړئ. او کله چې ستا پښه په دلدل کښې کېښودے شوه نو بيا يې تۀ خپل نصيب ته پرېښودلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18805, 'Jeremiah 38:23', 'Jeremiah', 38, 23, '&nbsp;ستاسو ټولې ښځې او ماشومان به بابليانو ته بهر راوويستلے شى، او تۀ به هم د هغوئ د نيولو نه بچ نۀ شې. تاسو به د بابل د بادشاه له خوا ګرفتار شئ، او دا ښار به وسوزيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18806, 'Jeremiah 38:24', 'Jeremiah', 38, 24, '&nbsp;نو بيا صدقياه يرمياه ته ووئيل چې، ”چا ته داسې ونۀ وائې چې تا ما ته دا خبره وکړه، ګنې تۀ به مړ ‎شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18807, 'Jeremiah 38:25', 'Jeremiah', 38, 25, '&nbsp;کۀ آفسرانو ته زما او ستا د ملاقات پته ولګى او راشى او ستا نه تپوس وکړى چې تاسو يو بل ته څۀ ووئيل نو مونږ ته سمه خبره وکړه او دروغ مۀ وايه ګنې مړ به دې کړُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18808, 'Jeremiah 38:26', 'Jeremiah', 38, 26, '&nbsp;نو بيا هغوئ ته ووايه چې ما بادشاه ته مِنت او زارى وکړه چې بيا مې د يونتن د کور تاخانې ته مۀ لېږه ګنې زۀ به هلته مړ شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18809, 'Jeremiah 38:27', 'Jeremiah', 38, 27, '&nbsp;هم هغه شان وشول، لږ وخت تېر شوے نۀ وو چې د بادشاه ټول آفسران راغلل او د يرمياه نه يې تپوسونه شروع کړل چې بادشاه د څۀ دپاره راغوښتے وې. خو يرمياه د بادشاه په هداياتو عمل وکړو. خو د بادشاه او د يرمياه په مينځ کښې شوې خبرې هيچا هم نۀ وې اورېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18810, 'Jeremiah 38:28', 'Jeremiah', 38, 28, '&nbsp;نو بيا يرمياه د دې نه وروستو د يروشلم د شکست پورې د فوجيانو په چاوڼۍ کښې بندى پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18811, 'Jeremiah 39:1', 'Jeremiah', 39, 1, '&nbsp;د صدقياه د بادشاهۍ د نهم کال په لسمه مياشت د بابل نبوکدنضر بادشاه د خپل ټول لښکر سره راغلو او د يروشلم نه يې ګېره واچوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18812, 'Jeremiah 39:2', 'Jeremiah', 39, 2, '&nbsp;د صدقياه د بادشاهۍ په يوولسم کال د څلورمې مياشتې په نهمه ورځ هغوئ د ښار دېوالونه مات کړل او ښار ته ورننوتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18813, 'Jeremiah 39:3', 'Jeremiah', 39, 3, '&nbsp;د يروشلم د نيولو نه وروستو، د بابل د بادشاه ټول فوجى آفسران د ښار د مينځنۍ دروازې سره خپله ډېره واچوله چې په هغوئ کښې نرګل‌شراضر د سمګر، او نيبو‌سرسکيم سر لښکر، او نرګل‌شراضر د بادشاه مشاور، او نور ټول آفسران شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18814, 'Jeremiah 39:4', 'Jeremiah', 39, 4, '&nbsp;کله چې صدقياه بادشاه او د هغۀ ټولو فوجيانو چې دا هر څۀ وليدل چې بابليان ښار ته راننوتل، نو هغوئ وتښتېدل. هغوئ شپه په شپه ښار پرېښودو او د شاهى باغ شا ته د دوه دېوالونو تر مينځه د دروازې د لارې نه بهر ووتل او د اُردن خوا ته روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18815, 'Jeremiah 39:5', 'Jeremiah', 39, 5, '&nbsp;خو د بابليانو لښکر ورپسې وو او د يريحو سره نزدې يې په هوار مېدان صدقياه ونيولو. هغوئ هغه د بابل نبوکدنضر بادشاه له بوتلو، څوک چې په رِبله کښې د حمات په علاقه کښې وو. هلته د بابل بادشاه په صدقياه د سزا فېصله واوروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18816, 'Jeremiah 39:6', 'Jeremiah', 39, 6, '&nbsp;هغۀ په رِبله کښې د صدقياه په وړاندې د صدقياه زامن او د يهوداه ټول مشران حلال کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18817, 'Jeremiah 39:7', 'Jeremiah', 39, 7, '&nbsp;بيا هغوئ د صدقياه سترګې راوويستلې او هغه يې د پيتلو په زنځيرونو وتړلو او بابل ته يې بندى بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18818, 'Jeremiah 39:8', 'Jeremiah', 39, 8, '&nbsp;په دې دوران کښې بابليانو يروشلم، شاهى محل او د خلقو کورونه وسوزول او د ښار دېوالونه يې وران کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18819, 'Jeremiah 39:9', 'Jeremiah', 39, 9, '&nbsp;بيا نبوزردان، د فوجيانو کمانډر هغه کسان چې ژوندى پاتې شوى وُو او کوم کسان چې بګوړه شوى وُو هغوئ يې بابل ته بنديوان بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18820, 'Jeremiah 39:10', 'Jeremiah', 39, 10, '&nbsp;خو نبوزردان لږ څۀ غريبانان خلق په يهوداه کښې پرېښودل چا چې زمکه نۀ لرله، او هغۀ هغوئ ته پټى او د انګورو باغونه په حواله کړل چې د هغې خيال ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18821, 'Jeremiah 39:11', 'Jeremiah', 39, 11, '&nbsp;خو نبوکدنضر بادشاه فوجى آفسر نبوزردان ته دا حکم وکړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18822, 'Jeremiah 39:12', 'Jeremiah', 39, 12, '&nbsp;”لاړ شئ او يرمياه پېدا کړئ او د هغۀ ښۀ خيال وساتئ. هغۀ له تکليف مۀ ورکوئ او هغه چې څۀ غواړى هغه ورله وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18823, 'Jeremiah 39:13', 'Jeremiah', 39, 13, '&nbsp;نو نبوزردان فوجى کمانډر، نبو‌شازبان مشر آفسر، نرګل‌شراضر د بادشاه مشاور، او د بابل بادشاه نورو ټولو آفسرانو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18824, 'Jeremiah 39:14', 'Jeremiah', 39, 14, '&nbsp;حکم وکړو چې يرمياه د فوجيانو چاوڼۍ نه رابهر کړئ. هغوئ هغه جدلياه د اخيقام زوئ او د سافن نمسى ته وسپارلو، چا چې هغه خپل کور ته واپس بوتلو. نو بيا هغه په يهوداه کښې د خپلو خلقو سره پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18825, 'Jeremiah 39:15', 'Jeremiah', 39, 15, '&nbsp;په کوم وخت کښې چې يرمياه په فوجى چاوڼۍ کښې بند وو، نو د مالِک خُدائ کلام په هغۀ نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18826, 'Jeremiah 39:16', 'Jeremiah', 39, 16, '&nbsp;”لاړ شئ او د ايتهوپيا عبيدمَلِک ته ووايئ چې مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، زۀ به د دې ښار سره هر هغه څۀ وکړم لکه څنګه چې ما هغوئ ته دهمکى ورکړې ده. زۀ به په هغوئ باندې افتونه نازل کړم، نه چې آبادى. تۀ به د هغوئ تباهى وګورې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18827, 'Jeremiah 39:17', 'Jeremiah', 39, 17, '&nbsp;خو په هغه ورځ به زۀ تا بچ کړم او تۀ به هغه چا ته حواله نۀ کړے شې د چا نه چې ستا په زړۀ کښې يره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18828, 'Jeremiah 39:18', 'Jeremiah', 39, 18, '&nbsp;ځکه چې تا په ما باور وکړو، زۀ به ستا ژوند تا ته درکړم. زۀ به تا بچ کړم او محفوظ به دې وساتم. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18829, 'Jeremiah 40:1', 'Jeremiah', 40, 1, '&nbsp;د مالِک خُدائ پېغام يرمياه ته پس د هغې نه ورکړے شو کله چې د فوج کمانډر نبوزردان هغه په راما کښې آزاد کړو. نو هغۀ يرمياه هم د يروشلم او يهوداه په هغه کسانو کښې په زنځيرونو تړلے وموندلو څوک چې بابل ته جلاوطن کېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18830, 'Jeremiah 40:2', 'Jeremiah', 40, 2, '&nbsp;د فوج کمانډر يرمياه ته آواز وکړو او ورته يې ووئيل چې، ”مالِک خُدائ ستا مقدس رب دا تباهى په دې مُلک نازله کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18831, 'Jeremiah 40:3', 'Jeremiah', 40, 3, '&nbsp;لکه څنګه چې هغۀ فرمائيلى وُو هغه شان يې وکړل. ځکه چې دې خلقو د مالِک خُدائ خلاف ګناه وکړه او د هغۀ نافرمانى يې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18832, 'Jeremiah 40:4', 'Jeremiah', 40, 4, '&nbsp;خو زۀ اوس ستا د لاسونو نه زنځيرونه اخوا کوم او تا آزادوم. کۀ تۀ ما سره بابل ته تلل غواړې، نو راځه چې ځُو. زۀ به ګورم چې ستا پوره خيال وساتلے شى. او کۀ تۀ ما سره هلته تلل نۀ غواړې، نو دلته ايسار شه. ټول مُلک ستا د وړاندې دے. چرته چې تۀ تلل غواړې نو هلته په آزاده توګه لاړ شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18833, 'Jeremiah 40:5', 'Jeremiah', 40, 5, '&nbsp;کۀ چرې تا دا فېصله کړې وى چې دلته پاتې شې، نو بيا جدلياه د اخيقام زوئ او د سافن نمسى ته واپس لاړ شه. هغه د بابل بادشاه له طرفه د يهوداه حکمران مقرر شوے دے. د هغه خلقو سره پاتې شه په چا چې هغه حکومت کوى. خو دا ستا خوښه ده، چرته دې چې زړۀ غواړى هلته لاړ شه.“ نو بيا نبوزردان يرمياه ته څۀ خوراک او پېسې ورکړې او هغۀ ته يې ووئيل چې لاړ شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18834, 'Jeremiah 40:6', 'Jeremiah', 40, 6, '&nbsp;نو بيا يرمياه جدلياه د اخيقام زوئ له په مصفاه کښې واپس لاړو، او هغه په يهوداه کښې د هغه خلقو سره اوسېدلو کوم چې په هغه مُلک کښې پاتې شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18835, 'Jeremiah 40:7', 'Jeremiah', 40, 7, '&nbsp;د يهوداه څۀ فوجى آفسران چې په کلى والو علاقو کښې پټ شوى وُو، هغوئ دا واورېدل چې په يهوداه کښې جدلياه د اخيقام زوئ په غريبانانو خلقو باندې د بابل بادشاه حکمران مقرر کړے دے. په هغوئ کښې نارينه، زنانه، او ماشومان شامل دى څوک چې بابل ته جلاوطن کړے شوى نۀ وُو او په يهوداه کښې پاتې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18836, 'Jeremiah 40:8', 'Jeremiah', 40, 8, '&nbsp;په هغوئ کښې دا آفسران شامل دى، اِسمٰعيل د نتنياه زوئ، يوحانان او يونتن د قريح زامن، شراياه د تنحومت زوئ، د عيفاى نطوفاتى زامن، يزنياه د معکاتى زوئ او د هغوئ فوجيان. هغوئ د جدلياه د ليدو دپاره مصفاه ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18837, 'Jeremiah 40:9', 'Jeremiah', 40, 9, '&nbsp;جدلياه د اخيقام زوئ او د سافن نمسى هغوئ سره په قسم خوړلو وعده وکړه چې، ”د خپل ځان په حواله کېدو بابليانو نه مۀ يرېږئ. د هغوئ د خِدمت کولو نه مۀ يرېږئ. په دې مُلک کښې اوسېږئ، او د بابل د بادشاه خِدمت کوئ او هر څۀ به ستاسو دپاره د خير وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18838, 'Jeremiah 40:10', 'Jeremiah', 40, 10, '&nbsp;زۀ به په خپله په مصفاه کښې اوسېږم او کله چې د بابليانو وفد دلته راشى نو زۀ به ستاسو د طرف نه نمائنده يم. خو په دې وخت کښې تاسو انګور، او د ګرمۍ مېوې، او د زيتُونو تېل په چاټو کښې جمع کړئ، او په کومو ښارونو مو چې قبضه کړې ده په هغوئ کښې اوسېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18839, 'Jeremiah 40:11', 'Jeremiah', 40, 11, '&nbsp;په دې دوران کښې چې کوم د يهوديانو خلق چې موآب، عمون، ادوم او نورو مُلکونو ته مسافر شوى وُو نو هغوئ ټول په دې خبر شول چې د بابل بادشاه د يهوداه پاتې شوى خلقو له په يهوداه کښې د اوسېدو اجازت ورکړے دے او جدلياه يې د هغوئ حکمران جوړ کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18840, 'Jeremiah 40:12', 'Jeremiah', 40, 12, '&nbsp;نو بيا هغوئ ټول د يهوداه مُلک ته واپس راغلل، په مصفاه کښې جدلياه ته، د هغه ټولو مُلکونو نه کوم ته چې هغوئ خوارۀ شوى وُو. او هغوئ د اوړى ډيرې مېوې او انګور راټول کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18841, 'Jeremiah 40:13', 'Jeremiah', 40, 13, '&nbsp;د هغې نه پس، د قريح زوئ يوحانان او هغه فوجى آفسران څوک چې په کلى والو علاقو کښې وُو، په مصفاه کښې جدلياه له راغلل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18842, 'Jeremiah 40:14', 'Jeremiah', 40, 14, '&nbsp;هغوئ هغۀ ته ووئيل چې، ”تا ته دا پته شته چې بعليس د عمون بادشاه اِسمٰعيل د نتنياه زوئ ستا د قتلولو دپاره رالېږلے دے؟“ خو جدلياه په دې خبره باندې يقين ونۀ کړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18843, 'Jeremiah 40:15', 'Jeremiah', 40, 15, '&nbsp;نو د قريح زوئ يوحانان هغۀ ته پټ غوندې ووئيل، ”ما پرېږده چې د نتنياه زوئ اِسمٰعيل ووژنم او هيچا ته به د دې پته ونۀ لګى. ولې مونږ هغۀ ته اجازت ورکړُو چې هغه راشى او تا ووژنى؟ د يهوداه د هغه خلقو به څۀ حال وى څوک چې واپس خپل مُلک ته راغلل او ستا په مشرۍ کښې راټول شول؟ نو بيا ولې دې مونږ د يهوداه دا لږ کسان کوم چې ژوندى يُو خوارۀ وارۀ او ورک شُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18844, 'Jeremiah 40:16', 'Jeremiah', 40, 16, '&nbsp;خو جدلياه يوحانان ته په جواب کښې ووئيل، ”زۀ تا په سختۍ سره منع کوم دا کار مۀ کوه. تۀ چې د اِسمٰعيل په حقله څۀ وائې نو هغه رښتيا نۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18845, 'Jeremiah 41:1', 'Jeremiah', 41, 1, '&nbsp;هم د هغه کال په اوومه مياشت، اِسمٰعيل د نتنياه زوئ او د اليسمع نمسے چې د شاهى خاندان يو کس وو، او د اوچتې عُهدې آفسر وو، هغه د لسو سړو سره مصفاه ته د جدلياه سره مِلاوېدو له لاړو. کله چې هغوئ په شريکه روټۍ خوړله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18846, 'Jeremiah 41:2', 'Jeremiah', 41, 2, '&nbsp;نو ناګهانه د نتنياه زوئ اِسمٰعيل او د هغۀ لسو کسانو ټوپ کړو او خپلې تُورې يې راوويستلې او جدلياه يې قتل کړو، څوک چې د بابل بادشاه په يهوداه کښې ګورنر مقرر کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18847, 'Jeremiah 41:3', 'Jeremiah', 41, 3, '&nbsp;اِسمٰعيل هم هغه ټول يهوديان ووژل څوک چې په مصفاه کښې د جدلياه سره وُو، او هغه بابليان فوجيان هم چې هلته وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18848, 'Jeremiah 41:4', 'Jeremiah', 41, 4, '&nbsp;د جدلياه د قتلېدو نه يوه ورځ وروستو چې لا څوک هم د هغۀ په مرګ باندې خبر نۀ وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18849, 'Jeremiah 41:5', 'Jeremiah', 41, 5, '&nbsp;اتيا کسان د شِکم، سيلا او سامريه نه د خُدائ کور ته راغلل چې عبادت وکړى. هغوئ خپلې ږيرې د غم په وجه خرئيلې وې، او د غم په وجه يې خپلې جامې هم شلولې وې او خپل ځانونه يې هم زخمى کړى وُو. او خپل ځان سره يې غله دانه او خوشبو مالِک خُدائ ته د نذرانې پېش کولو په توګه راوړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18850, 'Jeremiah 41:6', 'Jeremiah', 41, 6, '&nbsp;نو اِسمٰعيل د اوښکو نه په ډکو سترګو سره د مصفاه نه بهر ووتو او د هغه کسانو سره د ملاقات دپاره لاړو. کله چې هغه هغوئ ته ورسېدلو نو ورته يې ووئيل چې، ”راشئ، وګورئ چې د جدلياه د اخيقام زوئ سره څۀ شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18851, 'Jeremiah 41:7', 'Jeremiah', 41, 7, '&nbsp;خو چې څنګه هغوئ ښار ته ورننوتل، نو فوراً اِسمٰعيل او د هغۀ ملګرو ټول ووژل او د هغوئ لاشونه يې په يوه ډيګۍ کښې وروغورزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18852, 'Jeremiah 41:8', 'Jeremiah', 41, 8, '&nbsp;خو په هغه ډله کښې لس کسان وُو چې هغوئ اِسمٰعيل سره دا خبره وکړه او ورته يې ووئيل چې، ”کۀ چرې تۀ مونږ ونۀ وژنې نو کوم غنم، اوربشې، او د زيتون تېل او شات چې مونږ پټ ذخيره کړى دى هغه به تا له راوړُو.“ نو په دې خبره هغۀ هغوئ ژوندى پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18853, 'Jeremiah 41:9', 'Jeremiah', 41, 9, '&nbsp;هغه د اوبو ډيګۍ چې اِسمٰعيل په کښې د هغه مړو لاشونه ورګزار کړل کوم چې هغۀ وژلى وُو هم هغه لويه ډيګۍ وه چې آسا بادشاه جوړه کړې وه چې کله هغۀ د مصفاه دفاع مضبوطه کړه چې خپل ځان د اِسرائيلو د بعشا بادشاه نه وساتى. اِسمٰعيل د نتنياه زوئ هغه د مړو نه ډکه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18854, 'Jeremiah 41:10', 'Jeremiah', 41, 10, '&nbsp;بيا اِسمٰعيل د بادشاه لوڼه او هغه ټول کسان چې نبوزردان د فوج مشر په مصفاه کښې جدلياه ته پرېښى وُو هغوئ ټول يې ګېر کړل او ځان سره يې د عمون د علاقې په طرف روان کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18855, 'Jeremiah 41:11', 'Jeremiah', 41, 11, '&nbsp;خو کله چې يوحانان د قريح زوئ او نور د فوج مشران د اِسمٰعيل د جرم نه خبر شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18856, 'Jeremiah 41:12', 'Jeremiah', 41, 12, '&nbsp;نو هغوئ خپل ټول سپاهيان راټول کړل او هغۀ پسې راووتل او په جبعون کښې د لوئ تالاب سره نزدې هغوئ هغه پېدا کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18857, 'Jeremiah 41:13', 'Jeremiah', 41, 13, '&nbsp;کله چې د اِسمٰعيل سره قېديانو يوحانان او ورسره نور فوجى مشران وليدل نو هغوئ ډېر خوشحاله شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18858, 'Jeremiah 41:14', 'Jeremiah', 41, 14, '&nbsp;او د مصفاه نه ټول قېديان وتښتېدل او د يوحانان مدد يې شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18859, 'Jeremiah 41:15', 'Jeremiah', 41, 15, '&nbsp;خو اِسمٰعيل سره د خپلو هغه اتو کسانو دوستانو د عمون مُلک ته وتښتېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18860, 'Jeremiah 41:16', 'Jeremiah', 41, 16, '&nbsp;نو بيا يوحانان د قريح زوئ او نورو فوجى مشرانو، هغه ټول کسان د ځان سره روان کړل کوم چې هغوئ په جبعون کښې د اِسمٰعيل نه خلاص کړى وُو چې په هغوئ کښې سپاهيان، زنانه، ماشومان او د دربار خصيان شامل وُو، څوک چې د جدلياه د قتلولو نه وروستو اِسمٰعيل ګرفتار کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18861, 'Jeremiah 41:17', 'Jeremiah', 41, 17, '&nbsp;هغوئ مِصر ته د تللو وخت کښې د کِمهام سرائى چې بيت‌لحم سره نزدې وو هلته ايسار شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18862, 'Jeremiah 41:18', 'Jeremiah', 41, 18, '&nbsp;نو د دې يرې نه چې کۀ بابليان په دې موضوع خبر شى چې اِسمٰعيل جدلياه قتل کړے دے، هغه څوک چې د بابل بادشاه د يهوداه ګورنر مقررولو، نو هغوئ به بيا څۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18863, 'Jeremiah 42:1', 'Jeremiah', 42, 1, '&nbsp;نو بيا د فوج ټول جنګى مشران، يوحانان د قريح زوئ او يزنياه د هوسعياه زوئ، او د وړو نه تر لويو پورې ټول خلق', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18864, 'Jeremiah 42:2', 'Jeremiah', 42, 2, '&nbsp;يرمياه نبى ته راغلل او ورته يې ووئيل، ”مونږ ستا مِنت کوُو چې زمونږ دپاره د مالِک خُدائ ستا مقدس خُدائ نه دُعا وغواړه، کوم چې پاتې شوى کسان يُو. لکه څنګه چې تۀ وينې چې د مخکښې په مقابل کښې اوس مونږ ډېر لږ يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18865, 'Jeremiah 42:3', 'Jeremiah', 42, 3, '&nbsp;زمونږ دپاره دُعا وکړه چې مالِک خُدائ زمونږ خُدائ پاک مونږ ته لارښودنه وکړى چې څۀ وکړُو او چرته لاړ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18866, 'Jeremiah 42:4', 'Jeremiah', 42, 4, '&nbsp;يرمياه هغوئ ته په جواب کښې وفرمائيل چې، ”صحيح ده، زۀ به مالِک خُدائ ستاسو خُدائ پاک ته هم هغه شان دُعا وکړم لکه څنګه چې تاسو ما ته خواست وکړو، او زۀ به هر هغه څۀ تاسو ته ووايم چې هغه څۀ ما ته وفرمائى. زۀ به ستاسو نه هيڅ څيز هم نۀ پټوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18867, 'Jeremiah 42:5', 'Jeremiah', 42, 5, '&nbsp;بيا هغوئ يرمياه ته ووئيل، ”نو بيا دې مالِک خُدائ په مونږ په دې خبره رښتينے او وفادار ګواه وى کۀ چرې مونږ ستا په هغه ټولو خبرو عمل ونۀ کړو کومې چې مالِک خُدائ ستا خُدائ پاک زمونږ دپاره تا ته فرمائيلى دى چې تۀ يې مونږ ته بيان کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18868, 'Jeremiah 42:6', 'Jeremiah', 42, 6, '&nbsp;کۀ هغه کلام زمونږ خوښ شى او کۀ خوښ نۀ شى، مونږ به د مالِک خُدائ د کلام پيروى کوُو چا ته چې تۀ مونږ د خپل خواست دپاره لېږې. ځکه کۀ چرې مونږ د هغۀ د کلام پيروى وکړُو، نو هر څۀ به زمونږ دپاره د خير وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18869, 'Jeremiah 42:7', 'Jeremiah', 42, 7, '&nbsp;لس ورځې وروستو د مالِک خُدائ کلام په يرمياه نازل شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18870, 'Jeremiah 42:8', 'Jeremiah', 42, 8, '&nbsp;نو بيا هغۀ يوحنان د قريح زوئ او نورو فوجى آفسرانو ته، او ټولو خلقو لويو او وړو ته آواز وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18871, 'Jeremiah 42:9', 'Jeremiah', 42, 9, '&nbsp;هغۀ هغوئ ته وفرمائيل چې، ”تاسو زۀ مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک ته د خپل درخواست سره ولېږلم، هغه داسې فرمائى چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18872, 'Jeremiah 42:10', 'Jeremiah', 42, 10, '&nbsp;کۀ تاسو په دې مُلک کښې پاتې شئ، نو زۀ به تاسو بيا آباد کړم او نۀ به مو خرابوم، زۀ به تاسو وکرم او تاسو به د بېخ نه نۀ وباسم. زۀ ستاسو په هغه افت کوم چې ما په تاسو نازل کړے دے پښېمانه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18873, 'Jeremiah 42:11', 'Jeremiah', 42, 11, '&nbsp;مالِک خُدائ فرمائى چې، د بابل بادشاه نه نور مۀ يرېږئ. ځکه چې زۀ تاسو سره يم او د هغۀ نه به مو بچ کړم او د هغۀ د لاس نه به خلاصون درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18874, 'Jeremiah 42:12', 'Jeremiah', 42, 12, '&nbsp;زۀ به په تاسو دا رحم وکړم چې هغه به درباندې مهربانه کړم، نو بيا به هغه تاسو ته په خپل مُلک کښې د پاتې کېدو اجازت درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18875, 'Jeremiah 42:13', 'Jeremiah', 42, 13, '&nbsp;خو کۀ چرې تاسو د مالِک خُدائ ستاسو خُدائ پاک د دې پېغام نه اِنکار وکړئ، او کۀ چرې تاسو ووايئ چې، نه، مونږ به دلته نۀ پاتې کيږُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18876, 'Jeremiah 42:14', 'Jeremiah', 42, 14, '&nbsp;خو د دې په ځائ به مِصر ته لاړ شُو، چرته چې به مونږ د جنګونو، د جنګ د بيګل آوازونو او قحط نه آزاد شُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18877, 'Jeremiah 42:15', 'Jeremiah', 42, 15, '&nbsp;نو بيا تاسو د مالِک خُدائ پېغام د يهوداه پاتې خلقو ته واوروئ. مالِک خُدائ ربُ الافواج داسې فرمائى چې، کۀ چرې تاسو دا ضرور غوره کړئ چې مِصر ته لاړ شئ او هلته پاتې شئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18878, 'Jeremiah 42:16', 'Jeremiah', 42, 16, '&nbsp;د کوم جنګ او قحط نه چې تاسو يرېږئ نو هم هغه به تاسو راګېر کړى، او تاسو به هلته مړۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18879, 'Jeremiah 42:17', 'Jeremiah', 42, 17, '&nbsp;نو په حقيقت کښې چې څوک هم په تلو کلک ولاړ وى او هلته د اوسېدو اراده لرى نو هغه به په جنګ، قحط او په وبا مړ شى. په تاسو کښې به يو کس هم د هغه افت نه ونۀ تښتى کوم چې زۀ په تاسو باندې هلته راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18880, 'Jeremiah 42:18', 'Jeremiah', 42, 18, '&nbsp;مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، لکه څنګه چې زما قهر او غضب د يروشلم په خلقو نازل شوے وو، نو کۀ تاسو مِصر ته لاړئ نو زما غضب به په تاسو هم نازل شى. نو ستاسو نوم به د تل دپاره د لعنت، يرې او مسخرې په توګه اخستلے کيږى او خپل مُلک به دوباره ونۀ وينئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18881, 'Jeremiah 42:19', 'Jeremiah', 42, 19, '&nbsp;اے د يهوداه ژوندى پاتې شوى خلقو، مالِک خُدائ تاسو ته فرمائيلى دى چې مِصر ته مۀ ځئ. زۀ چې دا خبردارے نن تاسو ته درکوم دا مۀ هېروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18882, 'Jeremiah 42:20', 'Jeremiah', 42, 20, '&nbsp;ځکه تاسو چې کله زۀ مالِک خُدائ ته د خواست کولو دپاره ولېږلم نو تاسو غټه غلطى وکړه، ځکه چې تاسو ووئيل، د څۀ چې مالِک خُدائ مونږ ته حکم کړے دے هغه مونږ ته ووايه، مونږ به په هغې باندې پوره عمل کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18883, 'Jeremiah 42:21', 'Jeremiah', 42, 21, '&nbsp;خو ما تاسو ته نن د هغۀ حکم واورولو، خو تاسو تر اوسه پورې د مالِک خُدائ د هغه پېغام پيروى نۀ کوئ د کوم دپاره چې تاسو زۀ استولے وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18884, 'Jeremiah 42:22', 'Jeremiah', 42, 22, '&nbsp;نو اوس په دې خبره باندې يقين ساتئ چې، تاسو چې کوم ځائ ته تلل او اوسېدل غواړئ نو تاسو به هلته په جنګ، قحط او وبا مړۀ شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18885, 'Jeremiah 43:1', 'Jeremiah', 43, 1, '&nbsp;کله چې يرمياه د مالِک خُدائ د دوئ د خُدائ پاک هغه پېغام بيانول ټولو خلقو ته ختم کړو کوم يې چې دوئ ته رالېږلے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18886, 'Jeremiah 43:2', 'Jeremiah', 43, 2, '&nbsp;نو عزرياه د هوسعياه زوئ او يوحانان د قريح زوئ او نورو ټولو کبرژنو خلقو يرمياه ته ووئيل چې، ”تۀ دروغ وائې، مالِک خُدائ زمونږ خُدائ پاک مونږ کله هم مِصر ته د تلو نه منع کړى نۀ يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18887, 'Jeremiah 43:3', 'Jeremiah', 43, 3, '&nbsp;تۀ باروک د نيرياه زوئ په دې رضا کړے يې چې داسې خبرې کوه، ځکه هغه غواړى چې مونږ دلته پاتې شُو او د بابليانو د لاسه مړۀ شُو او يا بابل ته جلاوطن کړے شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18888, 'Jeremiah 43:4', 'Jeremiah', 43, 4, '&nbsp;نو بيا د قريح زوئ يوحانان او نورو فوجى مشرانو او نورو ټولو خلقو د مالِک خُدائ د حکم نه اِنکار وکړو چې په يهوداه کښې پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18889, 'Jeremiah 43:5', 'Jeremiah', 43, 5, '&nbsp;يوحنان او نورو مشرانو ځان سره ټول خلق بوتلل څوک چې د نزدې مُلکونو نه راواپس شوى وُو کوم ځائ ته چې دوئ خوارۀ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18890, 'Jeremiah 43:6', 'Jeremiah', 43, 6, '&nbsp;او په هغوئ کښې نارينه، زنانه، ماشومان، د بادشاه لوڼه، او ټول هغه خلق شامل وُو چې نبوزردان د محافظانو آفسر جدلياه ته سپارلى وُو. په دوئ کښې يرمياه پېغمبر او باروک هم شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18891, 'Jeremiah 43:7', 'Jeremiah', 43, 7, '&nbsp;خلقو د مالِک خُدائ د حکم نه اِنکار وکړو او د مِصر تحفنحيس ښار ته ورسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18892, 'Jeremiah 43:8', 'Jeremiah', 43, 8, '&nbsp;په تحفنحيس کښې مالِک خُدائ يرمياه ته بل پېغام ورکړو. هغۀ وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18893, 'Jeremiah 43:9', 'Jeremiah', 43, 9, '&nbsp;”کله چې د يهوداه خلق درته ګورى، نو دلته په تحفنحيس کښې يو څو غټ کاڼى راواخله او د فِرعون د محل په دروازه کښې يې د فرش لاندې ښخ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18894, 'Jeremiah 43:10', 'Jeremiah', 43, 10, '&nbsp;نو بيا د يهوداه خلقو ته ووايه چې، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې زۀ به په يقين سره خپل خِدمتګار نبوکدنضر د بابل بادشاه دلته مِصر ته راولم. زۀ به د هغۀ تخت په دې کاڼو دپاسه جوړ کړم کوم چې يرمياه دلته ښخ کړل. هغه به په دې کاڼو خپل شاهى تمبو وغوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18895, 'Jeremiah 43:11', 'Jeremiah', 43, 11, '&nbsp;او کله چې هغه راشى، نو هغه به د مِصر مُلک تباه کړى. هغه څوک به مړ کړى د چا دپاره چې د مرګ سزا مقرر شوې وى، د قېد سزا به هغۀ ته ورکړى چا ته چې د قېد سزا مقرر شوې وى، او څوک به په تُوره مړۀ کړى د چا دپاره چې په تُوره مړ کېدل مقرر شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18896, 'Jeremiah 43:12', 'Jeremiah', 43, 12, '&nbsp;هغه به د مِصر د معبودانو په مندرونو اور بل کړى، هغه به مندرونه وسوزوى او بُتان به قبضه کړى او د غنيمت په توګه به يې يوسى. هغه به د مِصر مال متاع داسې صفا کړى لکه څنګه چې يو شپون د خپلې چُوغې نه ورَږې صفا کوى. او بې‌نقصانه به هغه خپل مُلک ته واپس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18897, 'Jeremiah 43:13', 'Jeremiah', 43, 13, '&nbsp;هغه به د مِصر په بيت‌شمس مندر کښې مقدسې ستنې راوغورزوى کومې چې په هغې کښې ولاړې دى، او هغه به د مِصر د معبودانو مندرونه وسوزوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18898, 'Jeremiah 44:1', 'Jeremiah', 44, 1, '&nbsp;دا پېغام يرمياه ته د يهوداه د خلقو په حقله ورکړے شو څوک چې د مِصر په جنوبى ښارونو کښې لکه مجدال، تحفنحيس، ميمفِس او څوک چې په بره برخو کښې اوسېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18899, 'Jeremiah 44:2', 'Jeremiah', 44, 2, '&nbsp;”مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، تاسو هغه تباهى په خپله وليده چې کومه ما په يروشلم او د يهوداه په نورو ټولو ښارونو باندې راوستله. او نن دا شاړ او تباه شوى پراتۀ دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18900, 'Jeremiah 44:3', 'Jeremiah', 44, 3, '&nbsp;ځکه کوم بد کارونه چې هغوئ وکړل. هغوئ زما قهر په هغه خوشبو سوزولو او غېرو معبودانو ته په عبادت کولو راوچت کړو چې نۀ خو هغوئ او نۀ تاسو او نۀ د هغوئ پلار نيکۀ پېژندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');